CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', checkout_product_id text UNIQUE, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_order_id text NOT NULL, course_id uuid NOT NULL REFERENCES public.courses(id), email text NOT NULL, status text NOT NULL CHECK(status IN ('approved','pending','rejected','refunded','cancelled')), event_at timestamptz NOT NULL, UNIQUE(external_order_id,course_id));
GRANT SELECT ON public.purchases TO authenticated; GRANT ALL ON public.purchases TO service_role;
ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.purchase_email() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT lower(trim(email)) FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.purchase_email() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.purchase_email() TO authenticated,service_role;
CREATE FUNCTION public.can_access_course(course uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.purchases p JOIN public.courses c ON c.id=p.course_id WHERE c.id=course AND c.published AND p.email=public.purchase_email() AND p.status='approved') $$;
REVOKE ALL ON FUNCTION public.can_access_course(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_course(uuid) TO authenticated,service_role;
CREATE POLICY admin_courses ON public.courses FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY entitled_courses ON public.courses FOR SELECT TO authenticated USING(public.can_access_course(id));
CREATE POLICY own_purchases ON public.purchases FOR SELECT TO authenticated USING(email=public.purchase_email() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid REFERENCES public.courses(id) NOT NULL, title text NOT NULL, position integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.modules TO authenticated; GRANT ALL ON public.modules TO service_role;
ALTER TABLE public.modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_modules ON public.modules FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY student_modules ON public.modules FOR SELECT TO authenticated USING(public.can_access_course(course_id));
CREATE TABLE public.lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid REFERENCES public.modules(id) NOT NULL, title text NOT NULL, video_url text NOT NULL DEFAULT '', provider text NOT NULL DEFAULT 'direct' CHECK(provider IN ('direct','storage')), position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lessons TO authenticated; GRANT ALL ON public.lessons TO service_role;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_lesson(lesson uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE l.id=lesson AND l.published AND public.can_access_course(m.course_id)) $$;
REVOKE ALL ON FUNCTION public.can_access_lesson(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_lesson(uuid) TO authenticated,service_role;
CREATE POLICY admin_lessons ON public.lessons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY student_lessons ON public.lessons FOR SELECT TO authenticated USING(public.can_access_lesson(id));
CREATE TABLE public.materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid REFERENCES public.lessons(id) NOT NULL, title text NOT NULL, file_path text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.materials TO authenticated; GRANT ALL ON public.materials TO service_role;
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_materials ON public.materials FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY student_materials ON public.materials FOR SELECT TO authenticated USING(public.can_access_lesson(lesson_id));
CREATE TABLE public.lesson_progress (user_id uuid NOT NULL, lesson_id uuid REFERENCES public.lessons(id) NOT NULL, seconds numeric NOT NULL DEFAULT 0 CHECK(seconds>=0), completed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
GRANT SELECT,INSERT,UPDATE ON public.lesson_progress TO authenticated; GRANT ALL ON public.lesson_progress TO service_role;
ALTER TABLE public.lesson_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_progress ON public.lesson_progress FOR ALL TO authenticated USING(user_id=auth.uid() AND public.can_access_lesson(lesson_id)) WITH CHECK(user_id=auth.uid() AND public.can_access_lesson(lesson_id));
CREATE POLICY admin_files ON storage.objects FOR ALL TO authenticated USING(bucket_id='course-files' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='course-files' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY student_files ON storage.objects FOR SELECT TO authenticated USING(bucket_id='course-files' AND (EXISTS(SELECT 1 FROM public.lessons l WHERE l.provider='storage' AND l.video_url=name AND public.can_access_lesson(l.id)) OR EXISTS(SELECT 1 FROM public.materials m WHERE m.file_path=name AND public.can_access_lesson(m.lesson_id))));
CREATE INDEX purchases_email_course ON public.purchases(email,course_id); CREATE INDEX modules_course ON public.modules(course_id); CREATE INDEX lessons_module ON public.lessons(module_id); CREATE INDEX materials_lesson ON public.materials(lesson_id);
CREATE FUNCTION public.record_purchase(order_id text, product_id text, buyer_email text, payment_status text, occurred_at timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE course uuid; BEGIN SELECT id INTO course FROM public.courses WHERE checkout_product_id=product_id; IF course IS NULL THEN RAISE EXCEPTION 'Product is not linked to a course'; END IF; INSERT INTO public.purchases(external_order_id,course_id,email,status,event_at) VALUES(order_id,course,lower(trim(buyer_email)),payment_status,occurred_at) ON CONFLICT(external_order_id,course_id) DO UPDATE SET status=EXCLUDED.status,event_at=EXCLUDED.event_at WHERE purchases.event_at<EXCLUDED.event_at AND purchases.email=EXCLUDED.email; END $$;
REVOKE ALL ON FUNCTION public.record_purchase(text,text,text,text,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_purchase(text,text,text,text,timestamptz) TO service_role;